diff --git a/apps/weixin/src/main.rs b/apps/weixin/src/main.rs
--- a/apps/weixin/src/main.rs
+++ b/apps/weixin/src/main.rs
@@ -292,6 +292,9 @@ fn render_reply(value: &Value) -> String {
     if let Some(text) = value.as_str() {
         return text.to_string();
     }
+    if let Some(summary) = value.get("summary").and_then(Value::as_str) {
+        return summary.to_string();
+    }
     if let Some(output) = value.get("output").and_then(Value::as_str) {
         return output.to_string();
     }
diff --git a/installer/Zero3Pilot.iss b/installer/Zero3Pilot.iss
--- a/installer/Zero3Pilot.iss
+++ b/installer/Zero3Pilot.iss
@@ -50,7 +50,7 @@ function CommandExists(const Name: String): Boolean;
 var
   ResultCode: Integer;
 begin
-  Result := Exec(ExpandConstant('{cmd}'), '/C where \"' + Name + '\" >nul 2>nul', '', SW_HIDE,
+  Result := Exec(ExpandConstant('{cmd}'), '/C where "' + Name + '" >nul 2>nul', '', SW_HIDE,
     ewWaitUntilTerminated, ResultCode) and (ResultCode = 0);
 end;
